import { EVERY_SEMICOLON } from "../../regexps.js";
import { closedBySemicolon, trailingSemicolonAsked, valueAsClosed } from "../closedBySemicolon/index.js";
import { getBlockAfter } from "../getBlockAfter/index.js";
import { lastNodeHoldsTheBlockAfter } from "../lastNodeHoldsTheBlockAfter/index.js";
import { printsOnlyWhitespaceBehindTheColon } from "../runHeldForTheBlock/index.js";
import { setBlockAfter } from "../setBlockAfter/index.js";
import { straySemicolonsTaken, straySemicolonsTakenOwn } from "../straySemicolonsTaken/index.js";
import { isDeclaration } from "../typeGuards/index.js";
/**
 * Returns the raw in which PostCSS filed the stray semicolons behind the closing brace of a block's last node, with the run in front of them: that node's `raws.ownSemicolon`.
 * @param statement - The block's statement.
 * @returns The raw, or nothing where the last node has none.
 */
function ownSemicolonOfLast(statement) {
    let own = statement.last?.raws.ownSemicolon;
    return typeof own === `string` && own !== `` ? own : undefined;
}
/**
 * Returns the run between a block's last node and its closing brace as the file spells it: the block's final raw ({@link getBlockAfter}), behind the stray semicolons PostCSS filed with the run in front of them in the last node's `raws.ownSemicolon` where that node closes on a brace of its own.
 * @param syntax - The syntax the rule is built over, which reads the raw.
 * @param statement - The block's statement.
 * @returns The run, or undefined without a raw.
 */
export function getBlockTail(syntax, statement) {
    let after = getBlockAfter(syntax, statement);
    let own = ownSemicolonOfLast(statement);
    return own === undefined ? after : own + (after ?? ``);
}
/**
 * Writes the run between a block's last node and its closing brace, parting it back into the two raws {@link getBlockTail} joins: the last node's `raws.ownSemicolon` through as many semicolons as it held, the block's final raw the rest. A write keeps the semicolons in their order, so the ones the last node held are the first ones written.
 * @param syntax - The syntax the rule is built over, which writes the raw.
 * @param statement - The block's statement.
 * @param tail - The run to write.
 */
export function setBlockTail(syntax, statement, tail) {
    let own = ownSemicolonOfLast(statement);
    let last = statement.last;
    if (own === undefined || !last) {
        setBlockAfter(syntax, statement, tail);
        return;
    }
    let held = (own.match(EVERY_SEMICOLON) ?? []).length;
    let end = [...tail.matchAll(EVERY_SEMICOLON)][held - 1];
    let cut = end === undefined ? 0 : end.index + 1;
    last.raws.ownSemicolon = tail.slice(0, cut);
    setBlockAfter(syntax, statement, tail.slice(cut));
}
/**
 * Asks whether the run in front of the closing brace stands behind a semicolon once `declaration-block-trailing-semicolon` has run, although the parser now reads it as the value of the custom property closing the block: a live `always` writes the semicolon behind a value of whitespace or nothing, with no flag, which keeps its whitespace in front of that semicolon, so the run in front of the brace is the empty `raws.after` behind it.
 * @param syntax - The syntax the rule is built over, which reads the value.
 * @param statement - The block's statement.
 * @param result - The Stylelint result, which holds the configuration.
 * @returns True where the run is the block's `raws.after` behind that semicolon.
 */
export function runStandsBehindTheSemicolon(syntax, statement, result) {
    if (!lastNodeHoldsTheBlockAfter(statement))
        return false;
    let { last } = statement;
    return isDeclaration(last) && printsOnlyWhitespaceBehindTheColon(syntax, last, result) && trailingSemicolonAsked(last, result) === true;
}
/**
 * Returns the run {@link getBlockTail} returns as `declaration-block-trailing-semicolon` will leave it, so that a reader's answer is one whether that rule has run yet or not: behind a custom property whose value is whitespace or nothing, with no flag, that it writes a semicolon behind, the block's `raws.after` rather than the value.
 * @param syntax - The syntax the rule is built over, which reads the raw.
 * @param statement - The block's statement.
 * @param result - The Stylelint result, which holds the configuration.
 * @returns The run, or undefined without a raw.
 */
export function getBlockTailAsClosed(syntax, statement, result) {
    return runStandsBehindTheSemicolon(syntax, statement, result) ? statement.raws.after : getBlockTail(syntax, statement);
}
/**
 * Writes the run {@link getBlockTailAsClosed} reads where it reads it.
 * @param syntax - The syntax the rule is built over, which writes the raw.
 * @param statement - The block's statement.
 * @param result - The Stylelint result, which holds the configuration.
 * @param tail - The run to write.
 */
export function setBlockTailAsClosed(syntax, statement, result, tail) {
    if (runStandsBehindTheSemicolon(syntax, statement, result))
        statement.raws.after = tail;
    else
        setBlockTail(syntax, statement, tail);
}
/**
 * Finds the stray semicolons of the run {@link getBlockTail} returns that a neighbor takes out in the same run: those of the last node's `raws.ownSemicolon` and those of the block's final raw, each as its own question answers, counted in the joined run.
 * @param statement - The block's statement.
 * @param result - The Stylelint result, which holds the configuration.
 * @returns The semicolons' indices in the run.
 */
export function blockTailTaken(statement, result) {
    let own = ownSemicolonOfLast(statement);
    let after = lastNodeHoldsTheBlockAfter(statement) ? new Set() : straySemicolonsTaken(statement, result);
    if (own === undefined || !statement.last)
        return after;
    let shift = own.length;
    return new Set([...straySemicolonsTakenOwn(statement.last, result), ...[...after].map((index) => index + shift)]);
}
/**
 * Reads the text a brace rule asks its escape questions over as `declaration-block-trailing-semicolon` will leave it, where the block's last node is a declaration and the text ends with its value, its semicolon and the tail, or with the value holding the tail: a live `never` copy takes the semicolon with the whitespace in front of it, so the first whitespace character of the tail closes a hexadecimal escape ending the value, and a live `always` copy writes the semicolon behind the value, which closes the escape and leaves the tail a run whole. Any other text stands as it is, the tail where it is.
 * @param syntax - The syntax the rule is built over, which reads the value.
 * @param statement - The block's statement.
 * @param result - The Stylelint result, which holds the configuration.
 * @param text - The text the rule reads, ending with the tail and the closing brace.
 * @param tail - The run in front of the brace, as {@link getBlockTailAsClosed} reads it.
 * @returns The text as left, and where the tail opens in it.
 */
export function blockTextAsClosed(syntax, statement, result, text, tail) {
    let { last } = statement;
    let standing = { text, index: text.length - 1 - tail.length };
    if (!last || !isDeclaration(last) || last.important)
        return standing;
    // A custom property closing the block without a semicolon holds the tail in its value
    let held = lastNodeHoldsTheBlockAfter(statement);
    let value = syntax.read(last);
    let suffix = held ? `${value}}` : `${value}${statement.raws.semicolon ? `;` : ``}${tail}}`;
    if (!text.endsWith(suffix))
        return standing;
    let closedValue = valueAsClosed(syntax, last, result);
    if (held && closedValue.endsWith(tail))
        closedValue = closedValue.slice(0, closedValue.length - tail.length);
    let head = `${text.slice(0, text.length - suffix.length)}${closedValue}${closedBySemicolon(last, result) ? `;` : ``}`;
    return { text: `${head}${tail}}`, index: head.length };
}
